# Let's try a greedy/backtracking approach
import random

def solve(need, possible, fixed_set):
    # Sort vertices by need descending
    vertices_by_need = sorted([v for v in range(18) if need[v] > 0], key=lambda v: -need[v])

    if not vertices_by_need:
        return []

    # Pick the vertex with highest need
    v = vertices_by_need[0]

    # Find candidates that connect to v
    candidates = []
    for u in range(18):
        if u == v:
            continue
        if (min(u,v), max(u,v)) not in fixed_set:
            # Check if this edge would help
            candidates.append(u)

    # Sort candidates by their need (prefer those who also need edges)
    candidates.sort(key=lambda u: -need[u])

    for u in candidates:
        # Try adding edge (min(v,u), max(v,u))
        e = (min(v,u), max(v,u))
        new_need = need.copy()
        new_need[v] -= 1
        new_need[u] -= 1
        new_fixed = fixed_set | {e, (u,v)}

        # Quick check: no vertex should need more than available candidates
        ok = True
        for w in range(18):
            if new_need[w] > 0:
                # Count how many possible edges remain for w
                cnt = 0
                for x in range(18):
                    if x != w and (min(w,x), max(w,x)) not in new_fixed:
                        cnt += 1
                if cnt < new_need[w]:
                    ok = False
                    break
        if not ok:
            continue

        result = solve(new_need, possible, new_fixed)
        if result is not None:
            return [e] + result

    return None

